use crate::aap::caps::kb_read;

struct Node;

/// Upper bound on the question length, in characters. Bounding by characters
/// keeps both the character count and the UTF-8 byte length at or under 512.
const MAX_QUESTION_CHARS: usize = 512;

/// Placeholder used when the knowledge base returns nothing, so that the
/// output always carries at least one knowledge entry.
const NO_KNOWLEDGE: &str = "No knowledge-base entry matched this question.";

fn bound_question(question: &str) -> String {
    question.chars().take(MAX_QUESTION_CHARS).collect()
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let question = bound_question(&query.query.question);

        let mut knowledge = kb_read::lookup(&question);
        if knowledge.is_empty() {
            knowledge.push(NO_KNOWLEDGE.to_string());
        }

        ConversationContext {
            intent: query.query.intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
